const incoming = $input.first().json || {};

// n8n Webhook node usually puts POST body inside incoming.body.
// But if another node sends direct JSON, we also support incoming itself.
const rawBody = incoming.body !== undefined ? incoming.body : incoming;

// If body is empty, pass empty input to core normalizer.
// This allows core to return EMPTY_INPUT.
if (!rawBody || Object.keys(rawBody).length === 0) {
  return [
    {
      json: {}
    }
  ];
}

// If the incoming request already uses the internal { data, config } contract,
// pass it through unchanged.
if (rawBody.data && rawBody.config) {
  return [
    {
      json: rawBody
    }
  ];
}

// Otherwise convert external webhook shape into core component contract.
const coreInput = {
  data: {
    event_type: rawBody.event_type || null,
    source: rawBody.source || "webhook",
    origin: rawBody.origin || "manual_test",
    environment: rawBody.environment || "test",
    payload: rawBody.payload
  },
  config: {
    default_next_action:
      rawBody.next_action ||
      (rawBody.config && rawBody.config.default_next_action) ||
      "validate_payload",
    require_payload:
      rawBody.config && rawBody.config.require_payload !== undefined
        ? rawBody.config.require_payload
        : true
  }
};

return [
  {
    json: coreInput
  }
];
